
const defaults=[{code:'3',name:'Religação',urban:13325,rural:40642},{code:'5',name:'Corte simbólico',urban:7662,rural:39309},{code:'383',name:'Corte no ramal',urban:22653,rural:41308},{code:'236',name:'Negociação',urban:21320,rural:39976}];
const key='osfacil-v1';let state;try{state=JSON.parse(localStorage.getItem(key))}catch{}if(!state||typeof state!=='object'||Array.isArray(state))state={};
if(!Array.isArray(state.rates)||state.rates.length!==defaults.length||state.rates.some((r,i)=>r.code!==defaults[i].code||!Number.isSafeInteger(r.urban)||!Number.isSafeInteger(r.rural)||r.urban<0||r.rural<0))state.rates=structuredClone(defaults);
if(!state.days||typeof state.days!=='object'||Array.isArray(state.days))state.days={};
for(const d of Object.keys(state.days)){if(!Array.isArray(state.days[d])){delete state.days[d];continue}state.days[d]=state.days[d].filter(e=>e&&defaults.some(r=>r.code===e.code)&&['urban','rural'].includes(e.area)&&Number.isSafeInteger(e.price)&&e.price>=0)}
let page='today',area='urban';const localDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};let date=localDate(),month=date.slice(0,7);const money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const dayLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'});const entries=d=>state.days[d]||[];const sum=a=>a.reduce((n,e)=>n+e.price,0);const count=(code)=>entries(date).filter(e=>e.code===code&&e.area===area).length;
function notify(s){let t=document.getElementById('toast');t.textContent=s;t.hidden=false;clearTimeout(window.timer);window.timer=setTimeout(()=>t.hidden=true,3000)}
function save(){try{localStorage.setItem(key,JSON.stringify(state));return true}catch{notify('Não foi possível salvar. Libere espaço e tente novamente.');return false}}
function change(code,delta){const before=JSON.stringify(state);let a=state.days[date]||(state.days[date]=[]);if(delta>0){let r=state.rates.find(r=>r.code===code);a.push({code,area,price:r[area]})}else{let i=a.findLastIndex(e=>e.code===code&&e.area===area);if(i>=0)a.splice(i,1)}if(!a.length)delete state.days[date];if(!save())state=JSON.parse(before);render()}
function report(d){return `OS Fácil • ${dayLabel(d)}\n\n`+state.rates.flatMap(r=>['urban','rural'].map(a=>{let es=entries(d).filter(e=>e.code===r.code&&e.area===a);return es.length?`${r.code} • ${r.name} • ${a==='urban'?'Urbano':'Rural'}: ${es.length} OS / ${money(sum(es))}`:null})).filter(Boolean).join('\n')+`\n\nTotal: ${entries(d).length} OS • ${money(sum(entries(d)))}`}
async function share(){let text=report(date);if(window.Android){Android.share(text);return}try{if(navigator.share)await navigator.share({text});else{await navigator.clipboard.writeText(text);notify('Resumo copiado!')}}catch(e){if(e.name!=='AbortError'){let blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`OS-${date}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}}
function render(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));let app=document.getElementById('app');
if(page==='today'){let es=entries(date);app.innerHTML=`<div class="date"><div><h2>Meu dia</h2><small>Uma OS de cada vez.</small></div><input aria-label="Data dos serviços" id="date" type="date" value="${date}"></div><section class="hero"><small class="eyebrow">Total do dia</small><div class="money" data-cents="${sum(es)}">${money(sum(es))}</div><small>Seu resultado em serviços realizados</small><footer><span id="daily-count"><b>${es.length}</b> OS registradas</span><span>Salvo no aparelho ✓</span></footer></section><div class="tabs" aria-label="Área"><button data-area="urban" class="${area==='urban'?'active':''}">⌂ &nbsp; Urbano</button><button data-area="rural" class="${area==='rural'?'active':''}">♧ &nbsp; Rural</button></div><div class="section-head"><h2>Registrar serviço</h2><small>Toque em + ao concluir uma OS.</small></div>${state.rates.map(r=>`<article class="card"><div class="row"><div><span class="code">OS ${r.code}</span><div class="name">${r.name}</div><div class="price">${money(r[area])} por serviço</div></div><span class="chip">${area==='urban'?'Urbano':'Rural'}</span></div><div class="controls"><button data-code="${r.code}" data-delta="-1" aria-label="Remover ${r.name}" ${count(r.code)?'':'disabled'}>−</button><span class="count">${count(r.code)}</span><button class="plus" data-code="${r.code}" data-delta="1" aria-label="Adicionar ${r.name}">+</button><span class="subtotal" data-cents="${sum(es.filter(e=>e.code===r.code&&e.area===area))}">${money(sum(es.filter(e=>e.code===r.code&&e.area===area)))}</span></div></article>`).join('')}<button class="full" id="share">Compartilhar fechamento ↗</button><p class="note">O botão − remove o último registro desse serviço na área selecionada.</p>`;document.getElementById('date').onchange=e=>{if(e.target.value){date=e.target.value;render()}};app.querySelectorAll('[data-area]').forEach(b=>b.onclick=()=>{area=b.dataset.area;render()});app.querySelectorAll('[data-code]').forEach(b=>b.onclick=()=>change(b.dataset.code,Number(b.dataset.delta)));document.getElementById('share').onclick=share}
if(page==='history'){let ds=Object.keys(state.days).filter(d=>d.startsWith(month)).sort().reverse(),all=ds.flatMap(entries);app.innerHTML=`<div class="date"><h2>Histórico</h2><input id="month" aria-label="Mês do histórico" type="month" value="${month}"></div><section class="hero"><small class="eyebrow">Resultado do mês</small><div class="money">${money(sum(all))}</div><small>${all.length} OS em ${ds.length} dias trabalhados</small></section>${ds.length?ds.map(d=>`<article class="card"><div class="row"><button class="historydate" data-day="${d}">${dayLabel(d)} ↗</button><b>${money(sum(entries(d)))}</b></div><small>${entries(d).length} serviços realizados</small>${state.rates.map(r=>{let es=entries(d).filter(e=>e.code===r.code);return es.length?`<div class="row historyline"><span>${r.name} · ${es.length}</span><span>${money(sum(es))}</span></div>`:''}).join('')}</article>`).join(''):'<div class="empty">Nenhuma OS neste mês.<p>Seus registros aparecerão aqui.</p></div>'}<p class="note">Toque em uma data para consultar ou corrigir os registros.</p>`;document.getElementById('month').onchange=e=>{if(e.target.value){month=e.target.value;render()}};app.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{date=b.dataset.day;page='today';render()})}
if(page==='rates'){app.innerHTML=`<div class="date"><h2>Tarifas dos serviços</h2></div><p class="muted">Atualize os valores para os próximos registros. O histórico mantém o valor de cada OS na data do lançamento.</p><form id="rates">${state.rates.map(r=>`<section class="card"><span class="code">OS ${r.code}</span><div class="name">${r.name}</div><div class="rategrid">${['urban','rural'].map(a=>`<label>${a==='urban'?'Urbano':'Rural'} · R$<input required inputmode="decimal" name="${r.code}-${a}" value="${(r[a]/100).toFixed(2).replace('.',',')}" aria-label="${r.name} ${a==='urban'?'urbano':'rural'}"></label>`).join('')}</div></section>`).join('')}<button class="full">Salvar tarifas</button></form><p class="note">Dados salvos somente neste aparelho. Compartilhe os fechamentos para guardar uma cópia. Desinstalar o app ou limpar seus dados pode apagar os registros.</p>`;document.getElementById('rates').onsubmit=e=>{e.preventDefault();let data=new FormData(e.target),rates=structuredClone(state.rates);for(let r of rates)for(let a of ['urban','rural']){let s=data.get(`${r.code}-${a}`).trim();if(!/^\d{1,7}([,.]\d{1,2})?$/.test(s)){notify('Informe valores válidos, como 133,25.');return}r[a]=Math.round(Number(s.replace(',','.'))*100)}let old=state.rates;state.rates=rates;if(save())notify('Tarifas atualizadas!');else state.rates=old}}
}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();window.scrollTo(0,0)});render();
